node --input-type=module << 'EOF'
import {Ajv} from 'ajv';
import type {ErrorObject} from 'ajv';

const ajv = new Ajv({validateFormats: false});
const schema = {
  type: 'object',
  properties: {ssn: {type: 'string'}},
  required: ['ssn'],
};

const validate = ajv.compile(schema);
const result = validate({ssn: 123456789});

function formatValidationError(errors) {
  if (!errors || errors.length === 0) return 'Invalid input';
  const error = errors[0];
  if (error.keyword === 'required') {
    const params = error.params;
    return `Missing required field: ${params.missingProperty}`;
  }
  if (error.keyword !== 'type') {
    const path = error.instancePath;
    return `Invalid input at ${path}: ${error.message}`;
  }
  const path = error.instancePath;
  const instancePath = path || '/';
  const field = instancePath.startsWith('/') ? instancePath.slice(1) : instancePath;
  const params = error.params;
  const expectedType = Array.isArray(params.type) ? params.type.join(' or ') : params.type;
  return `Field '${field}' must be of type ${expectedType}`;
}

const message = formatValidationError(validate.errors);
console.log('Formatted message:', message);
console.log('Includes ssn:', message.includes('ssn'));
EOF

